function [eta1, F, G] = attitudeProcess(eta, omega, Ts)
%ATTITUDEPROCESS Euler step eta1 = eta + Ts*inv(W_eta)*omega with gyro input.
% F = d eta1/d eta (3x3), G = d eta1/d omega (3x3).
% Generated by deriveAttitudeJacobians.py - do not edit by hand.
phi = eta(1);
theta = eta(2);
psi = eta(3);
omega1 = omega(1);
omega2 = omega(2);
omega3 = omega(3);
t0 = tan(theta);
t1 = sin(phi);
t2 = omega2.*t1;
t3 = Ts.*t2;
t4 = cos(phi);
t5 = omega3.*t4;
t6 = Ts.*t5;
t7 = omega2.*t4;
t8 = Ts.*t7;
t9 = omega3.*t1;
t10 = Ts.*t9;
t11 = cos(theta);
t12 = 1./t11;
t13 = Ts.*(t2 + t5);
t14 = t13./t11.^2;
t15 = Ts.*t1;
t16 = Ts.*t4;
eta1 = [Ts.*omega1 + phi + t0.*t3 + t0.*t6; -t10 + t8 + theta; t12.*(psi.*t11 + t3 + t6)];
F = [-t0.*t10 + t0.*t8 + 1 t14 0; -t13 1 0; Ts.*t12.*(t7 - t9) t14.*sin(theta) 1];
G = [Ts t0.*t15 t0.*t16; 0 t16 -t15; 0 t12.*t15 t12.*t16];
end
